export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  const store = new Map<string, { count: number; windowStart: number }>();

  function getOrResetState(key: string, nowMs: number): { count: number; windowStart: number } {
    const state = store.get(key);
    if (!state || nowMs - state.windowStart >= WINDOW_MS) {
      const newState = { count: 0, windowStart: nowMs };
      store.set(key, newState);
      return newState;
    }
    return state;
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const state = getOrResetState(key, nowMs);
      if (state.count < LIMIT) {
        state.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      const state = getOrResetState(key, nowMs);
      return Math.max(0, LIMIT - state.count);
    },
    reset(key: string): void {
      store.delete(key);
    },
  };
}
