```typescript
interface Todo {
  id: number
  text: string
  completed: boolean
}

interface TodoApp {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  const todos = new Map<number, Todo>()
  let nextId = 1

  return {
    addTodo(text: string): Todo {
      const id = nextId++
      const todo: Todo = { id, text, completed: false }
      todos.set(id, todo)
      return todo
    },
    getTodo(id: number): Todo | undefined {
      return todos.get(id)
    },
    toggleTodo(id: number): void {
      const todo = todos.get(id)
      if (todo) {
        todo.completed = !todo.completed
      }
    },
    deleteTodo(id: number): boolean {
      return todos.delete(id)
    },
    listTodos(): Todo[] {
      return Array.from(todos.values())
    },
    listCompleted(): Todo[] {
      return Array.from(todos.values()).filter(todo => todo.completed)
    },
    listPending(): Todo[] {
      return Array.from(todos.values()).filter(todo => !todo.completed)
    },
    clearCompleted(): void {
      const idsToDelete: number[] = []
      for (const [id, todo] of todos.entries()) {
        if (todo.completed) {
          idsToDelete.push(id)
        }
      }
      for (const id of idsToDelete) {
        todos.delete(id)
      }
    },
  }
}
