type EventListener = (...args: any[]) => any;
type ListenerEntry = { fn: EventListener; once: boolean };

interface EventEmitter {
  on(event: string, listener: EventListener): void;
  once(event: string, listener: EventListener): void;
  off(event: string, listener: EventListener): void;
  emit(event: string, ...args: any[]): any[];
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, ListenerEntry[]>();

  function on(event: string, listener: EventListener): void {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    listeners.get(event)!.push({ fn: listener, once: false });
  }

  function once(event: string, listener: EventListener): void {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    listeners.get(event)!.push({ fn: listener, once: true });
  }

  function off(event: string, listener: EventListener): void {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return;

    const index = eventListeners.findIndex(entry => entry.fn === listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return [];

    const results: any[] = [];
    const currentListeners = [...eventListeners];

    for (let i = 0; i < currentListeners.length; i++) {
      const entry = currentListeners[i];
      const result = entry.fn(...args);
      results.push(result);
      if (entry.once) {
        const actualIndex = eventListeners.indexOf(entry);
        if (actualIndex !== -1) {
          eventListeners.splice(actualIndex, 1);
        }
      }
    }

    return results;
  }

  return {
    on,
    once,
    off,
    emit
  };
}
