export function createRateLimiter() {
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  type KeyState = {
    windowStart: number;
    count: number;
  };

  const state = new Map<string, KeyState>();

  function allow(key: string, nowMs: number): boolean {
    const currentState = state.get(key);

    if (currentState === undefined) {
      state.set(key, {
        windowStart: nowMs,
        count: 1
      });
      return true;
    }

    if (nowMs >= currentState.windowStart + WINDOW_MS) {
      currentState.windowStart = nowMs;
      currentState.count = 1;
      return true;
    }

    if (currentState.count < MAX_REQUESTS) {
      currentState.count++;
      return true;
    }

    return false;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return {
    allow,
    reset
  };
}
