type ListenerCallback = (...args: any[]) => any;

interface IEventEmitter {
  on(event: string, listener: ListenerCallback): IEventEmitter;
  once(event: string, listener: ListenerCallback): IEventEmitter;
  off(event: string, listener: ListenerCallback): IEventEmitter;
  emit(event: string, ...args: any[]): any[];
}

function createEventEmitter(): IEventEmitter {
  const eventListeners = new Map<string, ListenerCallback[]>();
  const onceFlags = new Map<string, Set<ListenerCallback>>();

  function on(event: string, listener: ListenerCallback): IEventEmitter {
    const list = eventListeners.get(event) ?? [];
    list.push(listener);
    eventListeners.set(event, list);
    return methods;
  }

  function once(event: string, listener: ListenerCallback): IEventEmitter {
    const list = eventListeners.get(event) ?? [];
    list.push(listener);
    eventListeners.set(event, list);

    if (!onceFlags.has(event)) {
      onceFlags.set(event, new Set());
    }
    onceFlags.get(event)!.add(listener);
    return methods;
  }

  function off(event: string, listener: ListenerCallback): IEventEmitter {
    const list = eventListeners.get(event);
    if (list) {
      const index = list.indexOf(listener);
      if (index !== -1) {
        list.splice(index, 1);
      }
    }

    const onceSet = onceFlags.get(event);
    if (onceSet) {
      onceSet.delete(listener);
    }
    return methods;
  }

  function emit(event: string, ...args: any[]): any[] {
    const list = eventListeners.get(event);
    const results: any[] = [];

    if (!list || list.length === 0) {
      return results;
    }

    const onceSet = onceFlags.get(event);

    for (const listener of list) {
      try {
        const result = listener(...args);
        results.push(result);
      } catch {
        // Ignore errors from listeners
      }
    }

    // Clean up one-time listeners
    if (onceSet) {
      eventListeners.set(event, list.filter(l => onceSet.has(l)));
      onceSet.clear();
    }

    return results;
  }

  const methods = { on, once, off, emit };

  return methods as IEventEmitter;
}

export { createEventEmitter };
