type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

function createEventEmitter(): EventEmitter {
  const listeners: Record<string, Listener[]> = {}

  function on(event: string, listener: Listener): number {
    if (!listeners[event]) {
      listeners[event] = []
    }
    listeners[event].push(listener)
    return listeners[event].length
  }

  function once(event: string, listener: Listener): number {
    const wrapped = (payload: unknown) => {
      listener(payload)
      off(event, wrapped)
    }
    if (!listeners[event]) {
      listeners[event] = []
    }
    listeners[event].push(wrapped)
    return listeners[event].length
  }

  function off(event: string, listener: Listener): boolean {
    if (!listeners[event]) {
      return false
    }
    const index = listeners[event].indexOf(listener)
    if (index === -1) {
      return false
    }
    listeners[event].splice(index, 1)
    return true
  }

  function emit(event: string, payload: unknown): unknown[] {
    if (!listeners[event]) {
      return []
    }
    const results: unknown[] = []
    for (const listener of listeners[event]) {
      results.push(listener(payload))
    }
    return results
  }

  function listenerCount(event: string): number {
    return listeners[event] ? listeners[event].length : 0
  }

  return {
    on,
    once,
    off,
    emit,
    listenerCount,
  }
}

export { createEventEmitter, type EventEmitter, type Listener }
