export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

interface Entry {
  value: unknown
  expiresAt: number
}

export function createTtlCache(): TtlCache {
  const entries = new Map<string, Entry>()
  const DEFAULT_TTL = 1000

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = DEFAULT_TTL): void {
      const expiresAt = ttlMs === 0 ? nowMs : nowMs + ttlMs
      entries.set(key, { value, expiresAt })
    },

    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key)
      if (!entry) {
        return undefined
      }
      if (nowMs >= entry.expiresAt) {
        entries.delete(key)
        return undefined
      }
      return entry.value
    },

    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key)
      if (!entry) {
        return false
      }
      if (nowMs >= entry.expiresAt) {
        return false
      }
      return true
    },

    delete(key: string): boolean {
      return entries.delete(key)
    },

    size(nowMs: number): number {
      let count = 0
      for (const entry of entries.values()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },

    clear(): void {
      entries.clear()
    }
  }
}
