  return {
    allow(key, nowMs) {
      const existing = state.get(key);

      if (!existing || nowMs >= existing.windowStart + WINDOW_MS) {
        state.set(key, { windowStart: nowMs, count: 1 });
        return true;
      }

      if (existing.count < MAX_REQUESTS) {
        existing.count++;
        return true;
      }

      return false;
    },

    reset(key) {
      state.delete(key);
    },
  };
