export function createEventEmitter() {
  const listeners: Map<string, Array<{ fn: (...args: unknown[]) => unknown; once: boolean }>> = new Map();

  function on(
    event: string,
    listener: (...args: unknown[]) => unknown,
    options?: { once: boolean }
  ): typeof on {
    const once = options?.once ?? false;
    const eventListeners = listeners.get(event) ?? [];
    listeners.set(event, eventListeners);
    eventListeners.push({ fn: listener, once });
    return on;
  }

  function off(event: string, listener: (...args: unknown[]) => unknown): typeof off {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return off;
    const idx = eventListeners.findIndex(({ fn }) => fn === listener);
    if (idx !== -1) {
      eventListeners.splice(idx, 1);
      if (eventListeners.length === 0) {
        listeners.delete(event);
      }
    }
    return off;
  }

  function once(event: string, listener: (...args: unknown[]) => unknown): typeof once {
    return on(event, listener, { once: true });
  }

  function emit(event: string, ...args: unknown[]): unknown[] {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return [];
    const results: unknown[] = [];
    const remaining: Array<{ fn: (...args: unknown[]) => unknown; once: boolean }> = [];
    for (const { fn, once } of eventListeners) {
      try {
        const result = fn(...args);
        results.push(result);
      } catch {
        results.push(undefined);
      }
      if (once) {
        continue;
      }
      remaining.push({ fn, once: false });
    }
    if (remaining.length === 0) {
      listeners.delete(event);
    } else {
      listeners.set(event, remaining);
    }
    return results;
  }

  function removeAllListeners(event?: string): typeof removeAllListeners {
    if (event === undefined) {
      listeners.clear();
    } else {
      listeners.delete(event);
    }
    return removeAllListeners;
  }

  return {
    on,
    on: Object.assign(on, { once }),
    off,
    once,
    emit,
    removeAllListeners,
  };
}
