export type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

interface RegisteredListener {
  id: number
  listener: Listener
  once: boolean
}

function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, RegisteredListener[]>()
  let nextId = 0

  return {
    on(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ id: nextId++, listener, once: false })
      return listeners.get(event)!.length
    },

    once(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, [])
      }
      listeners.get(event)!.push({ id: nextId++, listener, once: true })
      return listeners.get(event)!.length
    },

    off(event: string, listener: Listener): boolean {
      if (!listeners.has(event)) {
        return false
      }
      const list = listeners.get(event)!
      const index = list.findIndex((l) => l.listener === listener)
      if (index === -1) {
        return false
      }
      list.splice(index, 1)
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listeners.has(event)) {
        return []
      }
      const list = listeners.get(event)!
      const results: unknown[] = []

      const toRemove: number[] = []
      list.forEach((l, index) => {
        try {
          results.push(listener.call(null, payload))
        } catch (e) {
          results.push(e)
        }
        if (l.once) {
          toRemove.push(index)
        }
      })

      for (const index of toRemove) {
        const idx = list.findIndex((l, i) => i === index)
        if (idx !== -1) {
          list.splice(idx, 1)
        }
      }

      return results
    },

    listenerCount(event: string): number {
      return listeners.has(event) ? listeners.get(event)!.length : 0
    }
  }
}

export { createEventEmitter }
```

