export function createTodoApp() {
  let nextId = 1
  const todos: { id: number; text: string; completed: boolean }[] = []

  return {
    addTodo(text: string): { id: number; text: string; completed: boolean } {
      const newTodo = { id: nextId++, text, completed: false }
      todos.push(newTodo)
      return newTodo
    },

    getTodo(id: number): { id: number; text: string; completed: boolean } | undefined {
      return todos.find((todo) => todo.id === id)
    },

    toggleTodo(id: number): void {
      const todo = todos.find((t) => t.id === id)
      if (todo) {
        todo.completed = !todo.completed
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex((t) => t.id === id)
      if (index !== -1) {
        todos.splice(index, 1)
        return true
      }
      return false
    },

    listTodos(): { id: number; text: string; completed: boolean }[] {
      return Array.from(todos)
    },

    listCompleted(): { id: number; text: string; completed: boolean }[] {
      const result: { id: number; text: string; completed: boolean }[] = []
      for (const todo of todos) {
        if (todo.completed) {
          result.push(todo)
        }
      }
      return result
    },

    listPending(): { id: number; text: string; completed: boolean }[] {
      const result: { id: number; text: string; completed: boolean }[] = []
      for (const todo of todos) {
        if (!todo.completed) {
          result.push(todo)
        }
      }
      return result
    },

    clearCompleted(): void {
      const remaining: { id: number; text: string; completed: boolean }[] = []
      for (const todo of todos) {
        if (!todo.completed) {
          remaining.push(todo)
        }
      }
      todos.length = 0
      todos.push(...remaining)
    }
  }
}
